import{_ as a,I as d,o,c as i,j as t,a as n,J as c,ac as l}from"./chunks/framework.iusZwn-q.js";const b=JSON.parse('{"title":"Casing Configurations","description":"","frontmatter":{},"headers":[],"relativePath":"ts/casing-configuration.md","filePath":"ts/casing-configuration.md","lastUpdated":1790384886000}'),h={name:"ts/casing-configuration.md"};function r(p,e,u,g,m,k){const s=d("CopyOrDownloadAsMarkdownButtons");return o(),i("div",null,[e[0]||(e[0]=t("div",{style:{display:"none"},hidden:"true","aria-hidden":"true","data-nosnippet":""},"Are you an LLM? You can read better optimized documentation at /ts/casing-configuration.md for this page in Markdown format",-1)),e[1]||(e[1]=t("h1",{id:"casing-configurations",tabindex:"-1"},[n("Casing Configurations "),t("a",{class:"header-anchor",href:"#casing-configurations","aria-label":"Permalink to “Casing Configurations”"},"​")],-1)),c(s),e[2]||(e[2]=l(`<p>The <a href="https://github.com/abetwothree/laravel-ts-publish" target="_blank" rel="noreferrer">Laravel TypeScript Publisher</a> has three config options that set the casing of generated names: <code>models.relationship_case</code> for model relations, <code>enums.method_case</code> for enum methods, and <code>routes.method_casing</code> for route actions. Each one accepts <code>&#39;snake&#39;</code>, <code>&#39;camel&#39;</code>, or <code>&#39;pascal&#39;</code>, and each affects only its own feature. There&#39;s no global casing setting, and no attribute or <code>@tolki/ts</code> setup is involved.</p><h2 id="models-relationship-case" tabindex="-1"><code>models.relationship_case</code> <a class="header-anchor" href="#models-relationship-case" aria-label="Permalink to “models.relationship_case”">​</a></h2><p>This option sets the casing of relation names in generated model interfaces. See <a href="./models.html">Models</a> for how relations publish.</p><div class="language-php"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// config/ts-publish.php</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;models&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;relationship_case&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;snake&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// default</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span></code></pre></div><p>For a relation method named <code>ownedTeams()</code>, each value gives these names:</p><div class="table-scroll"><table tabindex="0"><thead><tr><th>Config Value</th><th>Relationship <code>ownedTeams()</code></th><th>Count</th><th>Exists</th></tr></thead><tbody><tr><td><code>&#39;snake&#39;</code></td><td><code>owned_teams: Team[]</code></td><td><code>owned_teams_count</code></td><td><code>owned_teams_exists</code></td></tr><tr><td><code>&#39;camel&#39;</code></td><td><code>ownedTeams: Team[]</code></td><td><code>ownedTeams_count</code></td><td><code>ownedTeams_exists</code></td></tr><tr><td><code>&#39;pascal&#39;</code></td><td><code>OwnedTeams: Team[]</code></td><td><code>OwnedTeams_count</code></td><td><code>OwnedTeams_exists</code></td></tr></tbody></table></div><p>Only the relation name is cased. The <code>_count</code> and <code>_exists</code> suffixes are added as they are, so <code>&#39;camel&#39;</code> gives you <code>ownedTeams_count</code>, not <code>ownedTeamsCount</code>.</p><div class="info custom-block"><p class="custom-block-title">Count and Exists Properties</p><p>For every relation on a model, the package also publishes a <code>_count</code> and an <code>_exists</code> property. They type the attributes that Laravel&#39;s <a href="https://laravel.com/docs/eloquent-relationships#counting-related-models" target="_blank" rel="noreferrer"><code>withCount</code> and <code>withExists</code></a> add, and they appear in every generated model&#39;s interfaces. Laravel always names these attributes in snake case, such as <code>owned_teams_count</code>. Under <code>&#39;camel&#39;</code> or <code>&#39;pascal&#39;</code>, the published <code>_count</code> and <code>_exists</code> names don&#39;t match them.</p></div><h2 id="enums-method-case" tabindex="-1"><code>enums.method_case</code> <a class="header-anchor" href="#enums-method-case" aria-label="Permalink to “enums.method_case”">​</a></h2><p>This option sets the casing of enum method and static method keys in the generated output. See <a href="./enums.html#enum-attributes">Enum Attributes</a> and <a href="./enums.html#auto-including-all-enum-methods">Auto-Including All Enum Methods</a> for which methods publish, through <code>#[TsEnumMethod]</code>, <code>#[TsEnumStaticMethod]</code>, and the <code>auto_include_methods</code> and <code>auto_include_static_methods</code> settings.</p><div class="language-php"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// config/ts-publish.php</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;enums&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;method_case&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;camel&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// default</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span></code></pre></div><p>For a method named <code>getLabel()</code> and a static method named <code>AllLabels()</code>, each value gives these keys:</p><div class="table-scroll"><table tabindex="0"><thead><tr><th>Config Value</th><th>Method <code>getLabel()</code></th><th>Static Method <code>AllLabels()</code></th></tr></thead><tbody><tr><td><code>&#39;snake&#39;</code></td><td><code>get_label</code></td><td><code>all_labels</code></td></tr><tr><td><code>&#39;camel&#39;</code></td><td><code>getLabel</code></td><td><code>allLabels</code></td></tr><tr><td><code>&#39;pascal&#39;</code></td><td><code>GetLabel</code></td><td><code>AllLabels</code></td></tr></tbody></table></div><div class="tip custom-block"><p class="custom-block-title">Renamed Methods Are Cased Too</p><p>The setting applies to every published enum method, instance or static, however it was included. You can rename one method with the <code>name</code> parameter of <code>#[TsEnumMethod]</code> or <code>#[TsEnumStaticMethod]</code>. That name goes through this setting as well, so under the default <code>&#39;camel&#39;</code>, <code>#[TsEnumMethod(name: &#39;get_label&#39;)]</code> publishes <code>getLabel</code>. Write the name in your configured casing to keep it as written. A case renamed with <code>#[TsCase(name:)]</code> isn&#39;t affected, and publishes exactly as written.</p></div><h2 id="routes-method-casing" tabindex="-1"><code>routes.method_casing</code> <a class="header-anchor" href="#routes-method-casing" aria-label="Permalink to “routes.method_casing”">​</a></h2><p>This option sets the casing of each route action&#39;s exported name. See <a href="./routing.html">Routing</a> for how routes publish. It changes only the generated export name. The Laravel route name stays the same, so <code>route()</code> and Ziggy calls still use it.</p><div class="language-php"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// config/ts-publish.php</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;routes&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;method_casing&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;camel&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// default</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span></code></pre></div><p>For controller methods named <code>updateProfile()</code> and <code>store()</code>, each value gives these export names:</p><div class="table-scroll"><table tabindex="0"><thead><tr><th>Config Value</th><th>Controller method <code>updateProfile()</code></th><th>Controller method <code>store()</code></th></tr></thead><tbody><tr><td><code>&#39;snake&#39;</code></td><td><code>update_profile</code></td><td><code>store</code></td></tr><tr><td><code>&#39;camel&#39;</code></td><td><code>updateProfile</code></td><td><code>store</code></td></tr><tr><td><code>&#39;pascal&#39;</code></td><td><code>UpdateProfile</code></td><td><code>Store</code></td></tr></tbody></table></div><div class="info custom-block"><p class="custom-block-title">Reserved Words</p><p>If the cased name is a reserved JavaScript word, such as <code>delete</code>, the package adds <code>Method</code> to it, so the export is <code>deleteMethod</code> and stays a valid identifier.</p></div><h2 id="configuration-reference" tabindex="-1">Configuration Reference <a class="header-anchor" href="#configuration-reference" aria-label="Permalink to “Configuration Reference”">​</a></h2><p>These are the three options and their defaults:</p><div class="table-scroll"><table tabindex="0"><thead><tr><th>Config Key</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>models.relationship_case</code></td><td><code>string</code></td><td><code>&#39;snake&#39;</code></td><td>Casing for relation names. The <code>_count</code> and <code>_exists</code> suffixes don&#39;t change</td></tr><tr><td><code>enums.method_case</code></td><td><code>string</code></td><td><code>&#39;camel&#39;</code></td><td>Casing for enum instance and static method keys</td></tr><tr><td><code>routes.method_casing</code></td><td><code>string</code></td><td><code>&#39;camel&#39;</code></td><td>Casing for each route action&#39;s exported name</td></tr></tbody></table></div><p>The full list of <code>models.*</code>, <code>enums.*</code>, and <code>routes.*</code> config keys is in the <a href="./configuration-reference.html">Configuration Reference</a>.</p>`,24))])}const y=a(h,[["render",r]]);export{b as __pageData,y as default};
